#!/usr/bin/env python3
"""
Round 138b (culprits-tiles-more), 2 October 2026.

lpi_populations.py: map tiles with boxes (the download is 46 MB as one file); skips
the zip's Mac copies; reads the header's byte-order mark.

Writes each file only if it differs. Run from the repository root.
"""
import base64, pathlib

FILES = {'scripts/lpi_populations.py': ''}


def main():
    for path, b64 in FILES.items():
        p = pathlib.Path(path)
        data = base64.b64decode(b64)
        if p.exists() and p.read_bytes() == data:
            print(f"round138b_tiles: {path} already as written")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        print(f"round138b_tiles: wrote {path}")


if __name__ == "__main__":
    main()
